function usableMyRenaultStatus(){const soc=Number(state.myRenault?.soc??state.myRenault?.batterySoc??state.myRenault?.batteryLevel);return state.myRenault?.ok&&!state.myRenault?.stale&&isValidSoc(soc)?{soc,status:state.myRenault.status||"connected",ageMinutes:state.myRenault.ageMinutes,timestamp:state.myRenault.timestamp,batteryAutonomy:state.myRenault.batteryAutonomy}:null;}
