function updateEvExternalStatus(plan){if(els.myRenaultStatus){if(plan.myRenault){els.myRenaultStatus.textContent=`Batteristatus fra MyRenault: ${formatSocSpaced(plan.startSoc)}${myRenaultUpdatedLabel(plan.myRenault)?` · senest opdateret ${myRenaultUpdatedLabel(plan.myRenault)}`:""}.`;}else if(state.myRenault?.stale&&isValidSoc(state.myRenault?.batteryLevel)){els.myRenaultStatus.textContent=`MyRenault batteristatus er gammel: ${formatSocSpaced(state.myRenault.batteryLevel)}${myRenaultUpdatedLabel(state.myRenault)?` · senest opdateret ${myRenaultUpdatedLabel(state.myRenault)}`:""}. Manuel batteristatus bruges.`;}else els.myRenaultStatus.textContent=state.myRenault?.message||"MyRenault ikke tilsluttet · Manuel batteristatus bruges.";}if(els.evWeatherStatus){if(plan.weatherSource==="automatic")els.evWeatherStatus.textContent=`Automatisk vejr aktivt · ${weatherInputLabel(plan)}.`;else els.evWeatherStatus.textContent=state.evWeather?.status==="error"?"Automatisk vejr ikke tilgængeligt · manuel vejrinput bruges.":"Automatisk vejr afventer rute · manuel vejrinput bruges.";}}
function calculateEvPlanner(){const v=evPlannerInputs();const batteryKwh=Number(v.profile.usableBatteryKwh);const routeProfile=plannerRouteProfile(v.routeDistanceKm);const routeRoadConsumptionKwh100=routeProfile.available?routeRoadConsumption(v.consumptionKwh100,routeProfile):v.consumptionKwh100;const weatherFactor=calculateEvWeatherFactor(v,!routeProfile.available);const adjustedConsumptionKwh100=routeRoadConsumptionKwh100*weatherFactor;const energyNeededKwh=v.routeDistanceKm*adjustedConsumptionKwh100/100;const socUsed=batteryKwh>0?energyNeededKwh/batteryKwh*100:null;const arrivalSoc=Number.isFinite(socUsed)?v.startSoc-socUsed:null;const reservePercentPoints=Number.isFinite(arrivalSoc)?arrivalSoc-v.minSoc:null;const safeEnergyKwh=Math.max(0,(v.startSoc-v.minSoc)/100*batteryKwh);const safeRangeKm=adjustedConsumptionKwh100>0?safeEnergyKwh/adjustedConsumptionKwh100*100:0;const missingPercentPoints=Number.isFinite(reservePercentPoints)?Math.max(0,-reservePercentPoints):0;const missingKwh=missingPercentPoints/100*batteryKwh;return{...v,batteryKwh,routeProfile,routeRoadConsumptionKwh100,weatherFactor,adjustedConsumptionKwh100,energyNeededKwh,socUsed,arrivalSoc,reservePercentPoints,safeRangeKm,missingKwh,missingPercentPoints,needsCharge:Number.isFinite(arrivalSoc)&&arrivalSoc<v.minSoc};}
