function evPlannerChargingSuggestions(plan){if(state.settings.mobilityType!=="charging")return{items:[],message:"Skift Type til Ladning og hent ladepunkter langs ruten for konkrete ladestop."};const selected=state.settings.chargeProvider||"all";const allPoints=dedupeChargingPoints(state.stations||[]).filter(isUsableChargingSuggestionPoint);const points=selected==="all"?allPoints:allPoints.filter(p=>p.providerKey===selected);if(!allPoints.length)return{items:[],message:"Ingen ladepunkter er hentet endnu. Tryk Opdater ladepunkter."};if(!points.length)return{items:[],message:"Ingen egnede ladepunkter fundet for valgt leverandør."};const safeRangeMeters=Math.max(0,Number(plan.safeRangeKm||0)*1000);const preferredMin=safeRangeMeters*0.70,preferredMax=safeRangeMeters*0.97,target=safeRangeMeters*0.85;const reachable=points.filter(p=>Number(p.distanceAlongRoute)<=safeRangeMeters);if(!reachable.length)return{items:[],message:selected==="all"?"Ingen egnede ladepunkter fundet før minimum-SoC-grænsen.":"Ingen egnede ladepunkter fundet for valgt leverandør."};const usefulReachable=preferUsefulChargingPower(reachable);const preferred=usefulReachable.filter(p=>Number(p.distanceAlongRoute)>=preferredMin&&Number(p.distanceAlongRoute)<=preferredMax);const fallback=usefulReachable.filter(p=>Number(p.distanceAlongRoute)<preferredMin||Number(p.distanceAlongRoute)>preferredMax);const usingPreferred=preferred.length>0;const pool=usingPreferred?preferred:fallback;const message=usingPreferred?"":fallback.some(p=>Number(p.distanceAlongRoute)<preferredMin)?`Tidligt ladestop foreslået, fordi der ikke blev fundet bedre senere ladepunkt${selected==="all"?"":" for valgt leverandør"}.`:"Ladestop ligger tæt på minimum-SoC-grænsen; kør med ekstra margin.";const items=[...pool].sort((a,b)=>usingPreferred?sortPreferredChargeStop(a,b,target):sortFallbackChargeStop(a,b)).slice(0,5);return{items,message};}
function selectedChargingProviderLabel(key){const option=[...(els.chargeProviderSelect?.options||[])].find(item=>item.value===key);return option?.textContent||key;}
function chargingMapsLinks(point){const lat=Number(point?.lat),lng=Number(point?.lng);const coords=Number.isFinite(lat)&&Number.isFinite(lng)?`${lat},${lng}`:"";const navigationUrl=coords?`https://www.google.com/maps/dir/?api=1&destination=${encodeURIComponent(coords)}&travelmode=driving`:"https://www.google.com/maps/search/?api=1&query=ladestation";const name=String(point?.name||"").trim();const provider=String(point?.provider||"").trim();const address=[point?.address,point?.street,point?.postalCode||point?.postal_code,point?.city].map(value=>String(value||"").trim()).filter(Boolean).join(" ");if(coords&&!name&&!provider&&!address)return{searchUrl:navigationUrl,navigationUrl};const generic=chargingPlaceNameIsGeneric(name,provider);const preciseParts=generic&&!address?[coords]:[name,provider,address,"elbil ladestation",coords];const query=preciseParts.filter(Boolean).join(" ")||coords||"ladestation";return{searchUrl:`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(query)}`,navigationUrl};}
function chargingPlaceNameIsGeneric(name,provider){const a=String(name||"").trim().toLowerCase(),b=String(provider||"").trim().toLowerCase();if(!a)return true;if(a===b)return true;return["clever","ionity","circle k","ok","norlys","spirii","tesla","e.on","q8/f24","uno-x"].includes(a);}
function dedupeChargingPoints(points){const kept=[];for(const point of points){const duplicate=kept.find(item=>sameChargingProvider(point,item)&&sameChargingSite(point,item));if(!duplicate){kept.push(point);continue;}if(chargingPointDataScore(point)>chargingPointDataScore(duplicate)){kept[kept.indexOf(duplicate)]=point;}}return kept;}
function sameChargingProvider(a,b){return String(a?.providerKey||a?.provider||"unknown").toLowerCase()===String(b?.providerKey||b?.provider||"unknown").toLowerCase();}
function sameChargingSite(a,b){const alat=Number(a?.lat),alng=Number(a?.lng),blat=Number(b?.lat),blng=Number(b?.lng);return Number.isFinite(alat)&&Number.isFinite(alng)&&Number.isFinite(blat)&&Number.isFinite(blng)&&distanceMeters(alat,alng,blat,blng)<=50;}
function chargingPointDataScore(point){return(Number(point.powerKw)||0)+(isValidChargePrice(point.priceKwh)?1000:0)+(point.connectorType?10:0)+chargingPointNameScore(point);}
function chargingPointNameScore(point){const name=String(point?.name||"").trim();return Math.min(name.length,80)+(point?.provider?20:0);}
function isUsableChargingSuggestionPoint(p){return Number.isFinite(Number(p.distanceAlongRoute))&&Number.isFinite(Number(p.distanceToRoute))&&Number.isFinite(Number(p.lat))&&Number.isFinite(Number(p.lng))&&(p.providerKey||p.connectorType||p.powerKw||"priceKwh"in p);}
function chargingPowerTier(point){const kw=Number(point?.powerKw||0);if(kw>=300)return 5;if(kw>=150)return 4;if(kw>=50)return 3;if(kw>=22)return 2;if(kw>=11)return 1;return 0;}
function preferUsefulChargingPower(points){const best=Math.max(...points.map(chargingPowerTier));if(best>=3)return points.filter(p=>chargingPowerTier(p)>=3);if(best>=2)return points.filter(p=>chargingPowerTier(p)>=2);if(best>=1)return points.filter(p=>chargingPowerTier(p)>=1);return points;}
function sortPreferredChargeStop(a,b,target){return Math.abs(Number(a.distanceAlongRoute)-target)-Math.abs(Number(b.distanceAlongRoute)-target)||Number(b.powerKw||0)-Number(a.powerKw||0)||Number(a.distanceToRoute||0)-Number(b.distanceToRoute||0);}
function sortFallbackChargeStop(a,b){return Number(b.distanceAlongRoute||0)-Number(a.distanceAlongRoute||0)||Number(b.powerKw||0)-Number(a.powerKw||0)||Number(a.distanceToRoute||0)-Number(b.distanceToRoute||0);}
function calculateEvWeatherFactor(plan,includeManualRoadType=true){let factor=1;const temp=Number(plan.temperatureC),wind=Number(plan.windKmh);if(temp<0)factor+=0.20+Math.min(0.10,Math.abs(temp)*0.006);else if(temp<5)factor+=0.12;else if(temp<10)factor+=0.06;else if(temp>30)factor+=0.08;else if(temp>25)factor+=0.04;if(wind>10)factor+=Math.min(0.15,(wind-10)*0.003);factor+=({none:0,rain:0.07,heavyRain:0.12,snow:0.20}[plan.precipitation]??0);if(includeManualRoadType)factor+=({city:-0.07,mixed:0,country:0.04,highway:0.16}[plan.roadType]??0);return Math.max(0.85,Math.min(1.60,factor));}
function routeProfileLabel(plan){const p=plan.routeProfile;if(!p?.available)return`Ruteprofil ikke tilgængelig — bruger valgt vejtype (${roadTypeLabel(plan.roadType)})`;const pct=p.percentages||{};const parts=[`${formatPct(pct.motorway)} motorvej`,`${formatPct(pct.rural)} landevej`,`${formatPct(pct.city)} by`];if(Number(pct.unknown)>0.5)parts.push(`${formatPct(pct.unknown)} ukendt`);return`Ruteprofil estimeret ud fra rutehastighed: ${parts.join(" · ")}`;}
function formatPct(value){const n=Number(value);return`${Number.isFinite(n)?Math.round(n):0} %`;}
function weatherInputLabel(plan){const road=plan.routeProfile?.available?"":`, ${roadTypeLabel(plan.roadType)}`;return `${Math.round(plan.temperatureC)}°C, ${Math.round(plan.windKmh)} km/t vind, ${precipitationLabel(plan.precipitation)}${road}`;}
function precipitationLabel(value){return{none:"tørt",rain:"regn",heavyRain:"kraftig regn",snow:"sne/slud"}[value]||"tørt";}
function roadTypeLabel(value){return{city:"by",mixed:"blandet vej",country:"landevej",highway:"motorvej"}[value]||"blandet vej";}
function ensureEvPlannerStyles(){if(document.getElementById("ev-planner-style"))return;const style=document.createElement("style");style.id="ev-planner-style";style.textContent=".ev-planner{margin-top:12px}.ev-profile-note,.ev-planner-note,.ev-planner-empty{color:var(--muted);font-size:13px}.ev-planner-grid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:10px;margin-top:12px}.ev-planner-grid label{display:block;color:var(--muted);font-size:12px;text-transform:uppercase}.ev-planner-grid input,.ev-planner-grid select{width:100%;margin-top:6px;background:#111f33;border:1px solid #31425d;border-radius:14px;padding:11px}.ev-compact .ev-planner-grid,.ev-compact .ev-profile-note,.ev-compact #myRenaultStatus,.ev-compact #evWeatherStatus{display:none}.ev-compact-summary{display:grid;gap:4px;margin-top:10px;color:#dce8f8}.ev-compact-summary strong{color:#fff;font-size:15px}.ev-compact-summary span{color:var(--muted);font-size:13px}.ev-details-toggle{margin-top:10px;background:transparent;border:1px solid var(--line);border-radius:12px;color:#d7ffe3;padding:9px 12px;font-weight:800}.ev-planner-kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(130px,1fr));gap:10px;margin-top:12px}.ev-planner-kpis div,.ev-planner-status{background:#101d2f;border:1px solid var(--line);border-radius:16px;padding:12px}.ev-planner-kpis span{display:block;color:var(--muted);font-size:11px;text-transform:uppercase}.ev-planner-kpis strong{display:block;margin-top:3px;font-size:20px;color:#fff}.ev-planner-status{margin-top:10px;color:#dce8f8}.ev-planner-status[data-level=ok]{border-color:rgba(57,228,123,.55)}.ev-planner-status[data-level=warn]{border-color:rgba(255,194,102,.65);color:#ffe3ad}.ev-planner-suggestions h3{margin:14px 0 4px;color:var(--muted);font-size:13px;text-transform:uppercase}@media(max-width:720px){.ev-planner-grid{grid-template-columns:1fr 1fr}.ev-planner-grid label:first-child{grid-column:1/-1}}";document.head.appendChild(style);}
function ensureRouteUiStyles(){if(document.getElementById("route-ev-ui-style"))return;const style=document.createElement("style");style.id="route-ev-ui-style";style.textContent=".trip.trip-with-battery{grid-template-columns:repeat(6,minmax(0,1fr))}.trip div[data-range-level=ok]{border-color:rgba(57,228,123,.65);background:rgba(57,228,123,.10)}.trip div[data-range-level=warn]{border-color:rgba(255,214,102,.70);background:rgba(255,214,102,.12)}.trip div[data-range-level=caution]{border-color:rgba(255,149,64,.80);background:rgba(255,149,64,.13)}.trip div[data-range-level=danger]{border-color:rgba(255,93,93,.85);background:rgba(255,93,93,.14)}.charge-stop-banner{margin:12px 0;background:#101d2f;border:1px solid rgba(57,228,123,.35);border-radius:16px;padding:12px;color:#dce8f8}.charge-stop-banner strong,.charge-stop-banner span{display:block}.charge-stop-banner span{color:var(--muted);font-size:13px;margin-top:4px}.charge-stop-warning{color:#ffe3ad!important}.charge-price-line,.charge-availability-line{margin-top:8px;color:#fff;font-weight:800}.charge-stop-actions{display:flex;flex-wrap:wrap;gap:8px;align-items:center;margin-top:10px}.charge-stop-actions button{background:#39e47b;color:#05210f;border:0;border-radius:12px;padding:9px 12px;font-weight:900}.charge-stop-actions #clearChargeStopBtn{background:transparent;color:#dce8f8;border:1px solid var(--line)}.charge-stop-actions a{color:#d7ffe3;font-weight:800;text-decoration:none}.charge-stop-actions .charge-operator-link{border:1px solid var(--line);border-radius:12px;padding:9px 12px}.charge-stop-actions .charge-operator-link:hover{border-color:rgba(57,228,123,.7)}@media(max-width:720px){.trip.trip-with-battery{grid-template-columns:repeat(2,minmax(0,1fr))}.charge-stop-actions{display:grid;grid-template-columns:1fr}.charge-stop-actions button,.charge-stop-actions a{width:100%;text-align:center}}";document.head.appendChild(style);}
function ensureRouteBatteryBoxes(){const trip=document.querySelector(".trip");if(!trip)return;ensureRouteUiStyles();trip.classList.add("trip-with-battery");if(!document.getElementById("routeBatteryCurrent"))trip.insertAdjacentHTML("beforeend",'<div><span>Aktuel batteri</span><strong id="routeBatteryCurrent">--</strong></div><div><span>Ved destination</span><strong id="routeBatteryArrival">--</strong></div>');if(!document.getElementById("routeBatteryRange"))trip.insertAdjacentHTML("beforeend",'<div><span>Rækkevidde</span><strong id="routeBatteryRange">--</strong></div>');els.routeBatteryCurrent=document.getElementById("routeBatteryCurrent");els.routeBatteryArrival=document.getElementById("routeBatteryArrival");els.routeBatteryRange=document.getElementById("routeBatteryRange");}
function renderRouteBatteryBoxes(plan){ensureRouteBatteryBoxes();if(!els.routeBatteryCurrent||!els.routeBatteryArrival||!els.routeBatteryRange)return;const current=Number(plan?.startSoc);const arrival=Number(plan?.arrivalSoc);const safeRange=Number(plan?.safeRangeKm);els.routeBatteryCurrent.textContent=isValidSoc(current)?formatSocSpaced(current):"--";els.routeBatteryArrival.textContent=plan?.routeDistanceKm&&Number.isFinite(arrival)?formatSocRawSpaced(arrival):"--";els.routeBatteryRange.textContent=Number.isFinite(safeRange)&&safeRange>0?`${Math.round(safeRange)} km`:"--";const rangeBox=els.routeBatteryRange.closest("div");if(rangeBox){const level=routeBatteryRangeLevel(plan);if(level)rangeBox.dataset.rangeLevel=level;else delete rangeBox.dataset.rangeLevel;}}
function routeBatteryRangeLevel(plan){const safeRange=Number(plan?.safeRangeKm),targetKm=Number(state.route?.distance)/1000;if(!Number.isFinite(safeRange)||safeRange<=0||!Number.isFinite(targetKm)||targetKm<=0)return"";const marginPercent=(safeRange-targetKm)/safeRange*100;if(marginPercent>15)return"ok";if(marginPercent>=10)return"warn";if(marginPercent>=5)return"caution";return"danger";}
function ensureChargeStopBanner(){const trip=document.querySelector(".trip");if(!trip)return;ensureRouteUiStyles();let banner=document.getElementById("chargeStopBanner");if(!banner){banner=document.createElement("section");banner.id="chargeStopBanner";banner.className="charge-stop-banner";banner.hidden=true;trip.insertAdjacentElement("afterend",banner);}els.chargeStopBanner=banner;}
function renderChargeStopBanner(){ensureChargeStopBanner();const banner=els.chargeStopBanner;if(!banner)return;const stop=state.temporaryChargeDestination;if(!stop){banner.hidden=true;banner.innerHTML="";return;}const original=state.originalDestination;const warning=String(stop.rangeWarning||"").trim();banner.hidden=false;banner.innerHTML=`<strong>Midlertidig destination: ${esc(destinationLabel(stop)||"Ladestop")}</strong><span>Efter ladestop: ${esc(destinationLabel(original)||"Oprindelig destination mangler")}</span>${warning?`<span class="charge-stop-warning">${esc(warning)}</span>`:""}<div class="charge-stop-actions"><button type="button" id="continueDestinationBtn">Fortsæt til slutdestination</button><button type="button" id="clearChargeStopBtn">Fjern ladestop</button></div>`;}
function destinationLabel(dest){return String(dest?.label||dest?.displayName||dest?.name||"").trim();}
function hasCoordinates(dest){return Number.isFinite(Number(dest?.lat))&&Number.isFinite(Number(dest?.lng));}
function chargePointLabel(point){const name=String(point?.name||"").trim(),provider=String(point?.provider||"").trim();return[name,provider].filter(Boolean).join(" · ")||"Ladestop";}
function isCurrentTemporaryChargeDestination(query,dest){const stop=state.temporaryChargeDestination;if(!stop||!hasCoordinates(stop)||!hasCoordinates(dest))return false;const sameCoords=Math.abs(Number(stop.lat)-Number(dest.lat))<0.000001&&Math.abs(Number(stop.lng)-Number(dest.lng))<0.000001;const sameLabel=destinationLabel(stop)&&destinationLabel(stop)===String(query||"").trim();return sameCoords||sameLabel;}
function numPlannerInput(el,fallback){const n=Number(String(el?.value??"").replace(",","."));return Number.isFinite(n)?n:fallback;}
function isValidSoc(value){const n=Number(value);return Number.isFinite(n)&&n>=0&&n<=100;}
function formatSoc(value){return `${Math.round(Math.max(0,Math.min(100,Number(value)||0)))}%`;}
function formatSocSpaced(value){return `${Math.round(Math.max(0,Math.min(100,Number(value)||0)))} %`;}
function formatSocRaw(value){const n=Number(value);return Number.isFinite(n)?`${Math.round(n)}%`:"--";}
function formatSocRawSpaced(value){const n=Number(value);return Number.isFinite(n)?`${Math.round(n)} %`:"--";}
function formatKwh(value){const n=Number(value);return Number.isFinite(n)?`${n.toFixed(1).replace(".",",")} kWh`:"-- kWh";}
function formatKwh100(value){return `${Number(value).toFixed(1).replace(".",",")} kWh/100 km`;}
function formatSignedPercent(value){const n=Number(value);const sign=n>0?"+":"";return `${sign}${n.toFixed(0).replace(".",",")}%`;}
function initMap(){if(typeof L==="undefined"){setStatus("Kort kunne ikke indlæses.");return;}state.map=L.map("map",{zoomControl:false,attributionControl:false,preferCanvas:true});L.tileLayer("https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}{r}.png",{subdomains:"abcd",maxZoom:20}).addTo(state.map);state.map.setView([55.6761,12.5683],10);}
async function searchAutocomplete(){const q=els.destinationInput.value.trim();if(q.length<2){hideAutocomplete();return;}try{const r=await fetch(`/api/geocode?q=${encodeURIComponent(q)}&limit=6&mode=suggest`,{cache:"no-store"});const d=await r.json();const items=Array.isArray(d)?d:(d.results||[]);if(!items.length){hideAutocomplete();return;}els.autocompleteResults.innerHTML=items.map((it,i)=>{const label=it.displayName||it.label||"Ukendt adresse",p=splitAddress(label);return `<button type="button" data-index="${i}"><strong>${esc(p.title)}</strong><small>${esc(p.subtitle)}</small></button>`;}).join("");els.autocompleteResults.classList.remove("hidden");[...els.autocompleteResults.querySelectorAll("button")].forEach(b=>b.addEventListener("click",()=>{const it=items[Number(b.dataset.index)],label=it.displayName||it.label||"Destination",p=splitAddress(label);state.selectedAutocomplete={lat:Number(it.lat),lng:Number(it.lng??it.lon),label:p.title,displayName:label};els.destinationInput.value=p.title;hideAutocomplete();}));}catch(e){console.warn(e);hideAutocomplete();}}
function hideAutocomplete(){els.autocompleteResults?.classList.add("hidden");}
async function calculateRoute(){const q=els.destinationInput.value.trim();if(!q){alert("Indtast en destination.");return;}try{const dest=state.selectedAutocomplete||await geocode(q);const keepTemporary=isCurrentTemporaryChargeDestination(q,dest);if(!keepTemporary){state.originalDestination=null;state.temporaryChargeDestination=null;}renderChargeStopBanner();await routeToKnownDestination(dest,{save:!keepTemporary});}catch(e){console.error(e);setStatus(`Fejl: ${e.message}`);}}
async function routeToKnownDestination(dest,{save=false}={}){try{setStatus("Finder position og beregner rute...");if(els.goBtn)els.goBtn.disabled=true;if(els.recalcBtn)els.recalcBtn.disabled=true;if(els.fuelRefreshBtn)els.fuelRefreshBtn.disabled=true;const pos=await getCurrentPosition();state.currentPosition=pos;updateCurrentMarker(pos,true);state.destination=dest;updateDestinationMarker(dest);if(save){saveHistory(dest);renderHistory();}const route=await fetchRoute(pos,dest);await applyRoute(route);if(els.recalcBtn)els.recalcBtn.disabled=false;if(els.fuelRefreshBtn)els.fuelRefreshBtn.disabled=false;setStatus(state.settings.mobilityType==="charging"?"Rute klar. Henter ladepunkter...":"Rute klar. Henter tankstationer...");await refreshFuel();}catch(e){console.error(e);setStatus(`Fejl: ${e.message}`);}finally{if(els.goBtn)els.goBtn.disabled=false;}}
function chargeStopPointFromButton(button){const index=Number(button?.dataset?.index);const list=button?.dataset?.list==="charging"?state.lastChargingList:state.lastEvPlannerSuggestions;return Number.isInteger(index)&&index>=0?list?.[index]:null;}
function chargeStopSelectionProblem(point){if(!state.route)return"Lav en rute først for at bruge ladestop.";if(!point||!hasCoordinates(point))return"Ladepunktet mangler koordinater.";const original=state.originalDestination||state.destination;if(!hasCoordinates(original))return"Oprindelig destination mangler.";return"";}
function chargeStopRangeWarning(point){try{const plan=calculateEvPlanner();const safeRangeMeters=Number(plan?.safeRangeKm)*1000,along=Number(point?.distanceAlongRoute);if(Number.isFinite(safeRangeMeters)&&safeRangeMeters>0&&Number.isFinite(along)&&along>safeRangeMeters)return"Dette ladepunkt ligger længere væk end beregnet rækkevidde.";}catch{}return"";}
function googleMapsChargerUrl(point){const lat=Number(point?.lat),lng=Number(point?.lng);if(!Number.isFinite(lat)||!Number.isFinite(lng))return"";return`https://www.google.com/maps/dir/?api=1&destination=${encodeURIComponent(`${lat},${lng}`)}&travelmode=driving`;}
function isMobileBrowser(){return typeof navigator!=="undefined"&&/iphone|ipad|ipod|android|mobile/i.test(navigator.userAgent||"");}
function openGoogleMapsToCharger(point){const url=googleMapsChargerUrl(point);if(!url){setStatus("Ladepunktet mangler koordinater.");return false;}try{if(isMobileBrowser()){window.location.href=url;return true;}const opened=window.open(url,"_blank","noopener");if(!opened)window.location.href=url;return true;}catch(e){console.warn("Could not open Google Maps:",e.message);try{window.location.href=url;return true;}catch{return false;}}}
function applyChargeStopSelection(point){const problem=chargeStopSelectionProblem(point);if(problem){setStatus(problem);return null;}const original=state.originalDestination||state.destination;state.originalDestination={...original};const label=chargePointLabel(point);const warning=chargeStopRangeWarning(point);const dest={lat:Number(point.lat),lng:Number(point.lng),label,displayName:label,name:point.name||label,provider:point.provider||"",rangeWarning:warning};state.temporaryChargeDestination=dest;state.destination=dest;state.selectedAutocomplete=dest;if(els.destinationInput)els.destinationInput.value=label;renderChargeStopBanner();if(warning)setStatus(warning);return dest;}
function openGoogleAndSelectChargeStop(button){const point=chargeStopPointFromButton(button);const dest=applyChargeStopSelection(point);if(!dest)return;const opened=openGoogleMapsToCharger(point);if(opened)void routeToKnownDestination(dest,{save:false});}
async function selectChargeStop(index){return selectChargeStopPoint(state.lastEvPlannerSuggestions?.[Number(index)]);}
async function selectChargeStopPoint(point){const dest=applyChargeStopSelection(point);if(dest)await routeToKnownDestination(dest,{save:false});}
async function continueToOriginalDestination(){const original=state.originalDestination;if(!hasCoordinates(original)){setStatus("Oprindelig destination mangler.");return;}state.temporaryChargeDestination=null;state.originalDestination=null;state.destination=original;state.selectedAutocomplete=original;if(els.destinationInput)els.destinationInput.value=destinationLabel(original);renderChargeStopBanner();await routeToKnownDestination(original,{save:false});}
async function clearChargeStop(){const original=state.originalDestination;state.temporaryChargeDestination=null;state.originalDestination=null;renderChargeStopBanner();if(hasCoordinates(original)){state.destination=original;state.selectedAutocomplete=original;if(els.destinationInput)els.destinationInput.value=destinationLabel(original);await routeToKnownDestination(original,{save:false});return;}setStatus("Ladestop fjernet.");}
async function geocode(q){const r=await fetch(`/api/geocode?q=${encodeURIComponent(q)}&limit=1`,{cache:"no-store"});const d=await r.json();const it=Array.isArray(d)?d[0]:(d.result||d.results?.[0]);if(!r.ok||!it)throw new Error(d.message||d.error||"Adresse ikke fundet");const lat=Number(it.lat),lng=Number(it.lng??it.lon);if(!Number.isFinite(lat)||!Number.isFinite(lng))throw new Error("Adresse uden koordinater");const label=it.displayName||it.label||q;return{lat,lng,label:splitAddress(label).title,displayName:label};}
async function fetchRoute(from,to){const avoid=state.settings.avoidFerries?"&avoid=ferries":"";const r=await fetch(`/api/route?fromLat=${from.lat}&fromLng=${from.lng}&toLat=${to.lat}&toLng=${to.lng}&mode=${encodeURIComponent(state.settings.routeMode)}${avoid}`,{cache:"no-store"});const d=await r.json();if(!r.ok||!d.routes?.length)throw new Error(d.error||"Ingen rute fundet");const route=selectRoute(d.routes);return{geometry:normalizeGeometry(route.geometry?.coordinates||route.geometry),distance:Number(route.distance||0),duration:Number(route.duration||0),roadProfile:buildRouteRoadProfile(route)};}
function selectRoute(routes){if(state.settings.routeMode!=="eco")return routes[0];return[...routes].sort((a,b)=>(a.distance+a.duration*4)-(b.distance+b.duration*4))[0];}
function buildRouteRoadProfile(route){const totalDistance=Number(route?.distance)||0;const buckets={cityKm:0,ruralKm:0,motorwayKm:0,unknownKm:0};let annotatedMeters=0;for(const leg of route?.legs||[]){const annotation=leg?.annotation||{};const distances=annotation.distance||[],durations=annotation.duration||[],speeds=annotation.speed||[];const count=Math.max(distances.length,durations.length,speeds.length);for(let i=0;i<count;i++){const dist=Number(distances[i]);const duration=Number(durations[i]);const speed=Number(speeds[i]);const meters=Number.isFinite(dist)&&dist>0?dist:(Number.isFinite(speed)&&speed>0&&Number.isFinite(duration)&&duration>0?speed*duration:0);if(meters<=0)continue;const speedKmh=Number.isFinite(speed)&&speed>0?speed*3.6:(Number.isFinite(duration)&&duration>0?meters/duration*3.6:null);addRoadProfileMeters(buckets,meters,speedKmh);annotatedMeters+=meters;}}if(annotatedMeters>0){const unknown=Math.max(0,totalDistance-annotatedMeters);buckets.unknownKm+=unknown/1000;return finalizeRoadProfile(buckets,totalDistance/1000,"speed-fallback");}if(totalDistance>0&&Number(route?.duration)>0)return buildAverageSpeedRouteProfile(totalDistance,Number(route.duration),"route-average-fallback");return finalizeRoadProfile({cityKm:0,ruralKm:0,motorwayKm:0,unknownKm:totalDistance/1000},totalDistance/1000,"unavailable");}
function buildAverageSpeedRouteProfile(distanceMeters,durationSeconds,source){const speedKmh=distanceMeters/durationSeconds*3.6;const buckets={cityKm:0,ruralKm:0,motorwayKm:0,unknownKm:0};addRoadProfileMeters(buckets,distanceMeters,speedKmh);return finalizeRoadProfile(buckets,distanceMeters/1000,source);}
function addRoadProfileMeters(buckets,meters,speedKmh){const km=meters/1000;if(!Number.isFinite(speedKmh)||speedKmh<=0)buckets.unknownKm+=km;else if(speedKmh<50)buckets.cityKm+=km;else if(speedKmh<90)buckets.ruralKm+=km;else buckets.motorwayKm+=km;}
function finalizeRoadProfile(buckets,totalKm,source){const total=Math.max(0,Number(totalKm)||0);const city=Number(buckets.cityKm)||0,rural=Number(buckets.ruralKm)||0,motorway=Number(buckets.motorwayKm)||0,unknown=Number(buckets.unknownKm)||0;const denominator=city+rural+motorway+unknown||total;return{available:source!=="unavailable"&&denominator>0,source,cityKm:city,ruralKm:rural,motorwayKm:motorway,unknownKm:unknown,totalKm:denominator,percentages:{city:denominator?city/denominator*100:0,rural:denominator?rural/denominator*100:0,motorway:denominator?motorway/denominator*100:0,unknown:denominator?unknown/denominator*100:0}};}
async function refreshEvWeather(){if(!state.route?.geometry?.length){state.evWeather={ok:false,status:"missing-route",message:"Automatisk vejr afventer rute."};return;}state.evWeather={ok:false,status:"loading",message:"Henter automatisk vejr..."};renderEvPlanner();try{const r=await fetch("/api/weather-route",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({geometry:state.route.geometry})});const d=await r.json().catch(()=>({}));if(!r.ok||!d.ok)throw new Error(d.error||`weather-route ${r.status}`);state.evWeather=d;applyAutoWeatherToInputs();}catch(e){console.warn(e);state.evWeather={ok:false,status:"error",message:"Automatisk vejr ikke tilgængeligt.",error:e.message};}}
async function applyRoute(route){state.route=route;state.evDetailsOpen=false;drawRoute(route.geometry);updateTrip(route);syncEvPlannerRouteDistance(true);await refreshEvWeather();renderEvPlanner();}
async function refreshFuel(){if(state.settings.mobilityType==="charging")return refreshCharging();if(!state.route)return;setFuelPanelMode();els.fuelRefreshBtn.disabled=true;els.fuelSummary.textContent="Henter tankstationer og priser...";try{const r=await fetch("/api/fuel-route",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({geometry:state.route.geometry,fuelType:state.settings.fuelType,maxDetourMeters:state.settings.maxFuelDetourMeters,fuelAlongMeters:state.settings.fuelAlongMeters})});const d=await r.json();if(!r.ok||!d.ok)throw new Error(d.error||`fuel-route ${r.status}`);state.stations=(d.stations||[]).map(s=>({...s,price:isValidFuelPrice(s.price)?Number(s.price):null,matchStatus:s.matchStatus||null,matchReason:s.matchReason||null,sourceStatus:s.sourceStatus||null,dataQuality:s.dataQuality||null})).sort(sortFuelStations);renderFuel(d);drawFuelMarkers();renderEvPlanner();}catch(e){console.error(e);els.fuelSummary.textContent=`Kunne ikke hente tankstationer: ${e.message}`;}finally{els.fuelRefreshBtn.disabled=false;}}
