function normalizeChargePriceFields(point){return{priceKwh:isValidChargePrice(point.priceKwh)?Number(point.priceKwh):null,priceMinKwh:isValidChargePrice(point.priceMinKwh)?Number(point.priceMinKwh):null,priceMaxKwh:isValidChargePrice(point.priceMaxKwh)?Number(point.priceMaxKwh):null,priceCurrency:point.priceCurrency||"DKK",priceLabel:point.priceLabel||"Pris ikke tilgængelig",priceSource:point.priceSource||"none",priceSourceUrl:point.priceSourceUrl||null,priceUpdatedAt:point.priceUpdatedAt||null,priceIsLive:Boolean(point.priceIsLive),priceIsStationSpecific:Boolean(point.priceIsStationSpecific),priceConfidence:point.priceConfidence||"none",priceQuality:point.priceQuality||"unknown"};}
